/** What only the call site knows. `path` is the only field a relocation touches, and is a
 *  function for node-type rows so one entry expands per node type. */
export type AuthoredSetting = {
  /** Set when the value is nested, e.g. Export rows under `GLOBAL_KEYS.export`. */
  parent?: SettingKeyId;
  label: string;
  group?: string;
  description?: string;
  docsLink?: string;
  /** Synonyms plus the retired Personal/Global tab names, so users searching by the old
   *  split still find a setting after the move to topic sections. */
  keywords?: readonly string[];
  /** Omitted when the setting lives outside Settings (Export options are in the Export
   *  dialog): still authored for its description, but not offered by search. */
  path?: SettingsPath | ((nodeTypeUid: string) => SettingsPath);
  /** Settings a graph cannot reach are dropped rather than offered as dead ends. */
  isAvailable?: () => boolean;
};

export type SearchableSetting = {
  kind: "setting";
  /** Unique per result; the anchor value plus the node uid for per-node rows. */
  id: string;
  anchorId: string;
  label: string;
  description?: string;
  keywords: readonly string[];
  path: SettingsPath;
  breadcrumb: string;
  /** Set on entries repeated per node type, whose shared breadcrumb is not matched. */
  nodeTypeUid?: string;
};

